/**
 * client.mjs — paginated consumer for the /orders API.
 * Contract source of truth: ../backend/contract.json
 *   request:  { page: integer starting at 1 }
 *   response: { items: array of { id: string }, next_page: integer or null }
 *
 * Exports fetchAll(fetchPage) -> flat array of order items across all pages.
 */

export async function fetchAll(fetchPage) {
  const items = [];
  let page = 1; // pages are 1-indexed per contract
  while (page != null) {
    const data = await fetchPage({ page });
    // Stack-safe accumulation (spread can overflow on very large pages).
    for (const item of data.items) items.push(item);
    page = data.next_page; // null terminates the loop
  }
  return items;
}
